} from '../core/integer.mjs';

function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

function buildHelpText(programName) {
  return `${buildUsage(programName)}

options:
  -h, --help  show this help message and exit
  --a A
  --b B`;
}

function buildErrorText(programName, message) {
  return `${buildUsage(programName)}
${programName}: error: ${message}`;
}

function buildRequiredMessage(missingOptions) {
  return `the following arguments are required: ${missingOptions.join(', ')}`;
}

function parseOptionValue(rawValue, optionName, programName) {
  try {
    return parseIntegerLiteral(rawValue, optionName);
  } catch (error) {
    return {
      kind: 'error',
      code: 2,
      text: buildErrorText(programName, error.message),
    };
  }
}

function parseInlineOption(token, optionName, programName) {
  return parseOptionValue(token.slice(optionName.length + 1), optionName, programName);
}

export function parseArgs(argv, programName) {
  let a;
  let b;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return {
        kind: 'help',
        code: 0,
        text: buildHelpText(programName),
      };
    }

    if (token === '--a' || token === '--b') {
      const rawValue = argv[index + 1];

      if (
        rawValue === undefined ||
        (rawValue.startsWith('-') && !looksLikeNegativeIntegerToken(rawValue))
      ) {
        return {
          kind: 'error',
          code: 2,
          text: buildErrorText(programName, `argument ${token}: expected one argument`),
        };
      }

      const parsedValue = parseOptionValue(rawValue, token, programName);
      if (parsedValue?.kind === 'error') {
        return parsedValue;
      }

      if (token === '--a') {
        a = parsedValue;
      } else {
        b = parsedValue;
      }

      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      const parsedValue = parseInlineOption(token, '--a', programName);
      if (parsedValue?.kind === 'error') {
        return parsedValue;
      }

      a = parsedValue;
      continue;
    }

    if (token.startsWith('--b=')) {
      const parsedValue = parseInlineOption(token, '--b', programName);
      if (parsedValue?.kind === 'error') {
        return parsedValue;
      }

      b = parsedValue;
      continue;
    }

    extras.push(token);
  }

  const missingOptions = [];
  if (a === undefined) {
    missingOptions.push('--a');
  }
  if (b === undefined) {
    missingOptions.push('--b');
  }

  if (missingOptions.length > 0) {
    return {
      kind: 'error',
      code: 2,
      text: buildErrorText(programName, buildRequiredMessage(missingOptions)),
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      code: 2,
      text: buildErrorText(programName, `unrecognized arguments: ${extras.join(' ')}`),
